mapper.select:
SELECT COUNT(DISTINCT DeviceID)
FROM RSWS_TempMonitor_Copy

    AND Workshop = '1#办公楼'

        AND UpdateTime >= #{startTime}


        AND UpdateTime <= #{endTime}

WITH LatestDeviceData AS ( SELECT DeviceID, Tem, Hum, ElectricEnergy, UpdateTime, Workshop, ROW_NUMBER() OVER (PARTITION BY DeviceID ORDER BY UpdateTime DESC) as rn FROM RSWS_TempMonitor_Copy
AND Workshop = '1#办公楼'
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) SELECT AVG(Tem) as avgTemperature, MIN(Tem) as minTemperature, MAX(Tem) as maxTemperature, AVG(Hum) as avgHumidity, MIN(Hum) as minHumidity, MAX(Hum) as maxHumidity, SUM(ElectricEnergy) as totalElectricEnergy, AVG(ElectricEnergy) as avgElectricEnergy FROM LatestDeviceData WHERE rn = 1

SELECT *
FROM RSWS_TempMonitor_Copy
WHERE Workshop = '1#办公楼'

    AND DeviceID = #{deviceId}


    AND Name = #{name}


    AND UpdateTime >= #{startTime}


    AND UpdateTime <= #{endTime}

ORDER BY UpdateTime DESC
OFFSET #{offset} ROWS
FETCH NEXT #{pageSize} ROWS ONLY

SELECT COUNT(*)
FROM RSWS_TempMonitor_Copy
WHERE Workshop = '1#办公楼'

    AND DeviceID = #{deviceId}


    AND Name = #{name}


    AND UpdateTime >= #{startTime}


    AND UpdateTime <= #{endTime}

WITH HourlyBoundaries AS ( -- 生成最近24小时的每个小时边界 SELECT DATEADD(HOUR, DATEDIFF(HOUR, 0, DATEADD(DAY, -1, GETDATE())) + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, 0) as HourStart, DATEADD(HOUR, DATEDIFF(HOUR, 0, DATEADD(DAY, -1, GETDATE())) + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)), 0) as HourEnd FROM ( SELECT TOP 24 1 as DummyColumn FROM sys.objects a CROSS JOIN sys.objects b ) dummy ), DeviceHourlyData AS ( SELECT HourStart, HourEnd, SUM( CASE WHEN tm_start.ElectricEnergy IS NOT NULL THEN tm_start.ElectricEnergy ELSE 0 END ) as StartEnergy, SUM( CASE WHEN tm_end.ElectricEnergy IS NOT NULL THEN tm_end.ElectricEnergy ELSE 0 END ) as EndEnergy, MIN(tm_start.UpdateTime) as StartTime, MAX(tm_end.UpdateTime) as EndTime FROM HourlyBoundaries hb CROSS JOIN ( SELECT DISTINCT DeviceID, Name, Workshop FROM RSWS_TempMonitor_Copy WHERE Workshop = '1#办公楼' AND ElectricEnergy IS NOT NULL
AND DeviceID = #{deviceId}
) devices LEFT JOIN RSWS_TempMonitor_Copy tm_start ON ( tm_start.DeviceID = devices.DeviceID AND tm_start.Name = devices.Name AND tm_start.Workshop = '1#办公楼' AND tm_start.ElectricEnergy IS NOT NULL AND tm_start.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '1#办公楼' AND inner_tm.UpdateTime <= hb.HourStart AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime DESC ) ) LEFT JOIN RSWS_TempMonitor_Copy tm_end ON ( tm_end.DeviceID = devices.DeviceID AND tm_end.Name = devices.Name AND tm_end.Workshop = '1#办公楼' AND tm_end.ElectricEnergy IS NOT NULL AND tm_end.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '1#办公楼' AND inner_tm.UpdateTime >= hb.HourEnd AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime ASC ) ) GROUP BY HourStart, HourEnd ) SELECT '1#办公楼' as deviceId, '1#办公楼' as name, '1#办公楼' as workshop, HourStart as hour, StartEnergy as startEnergy, EndEnergy as endEnergy, StartTime as startTime, EndTime as endTime, CASE WHEN StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE NULL END as energyConsumption FROM DeviceHourlyData WHERE StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL ORDER BY HourStart

WITH HourlyBoundaries AS ( -- 生成时间范围内的每个小时边界 SELECT DATEADD(HOUR, DATEDIFF(HOUR, 0, #{startTime} DATEADD(DAY, -7, GETDATE()) ) + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, 0) as HourStart, DATEADD(HOUR, DATEDIFF(HOUR, 0, #{startTime} DATEADD(DAY, -7, GETDATE()) ) + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)), 0) as HourEnd FROM ( SELECT TOP ( DATEDIFF(HOUR, #{startTime} DATEADD(DAY, -7, GETDATE()), #{endTime} GETDATE() ) + 1 ) 1 as DummyColumn FROM sys.objects a CROSS JOIN sys.objects b ) dummy ), DeviceHourlyData AS ( SELECT HourStart, HourEnd, SUM( CASE WHEN tm_start.ElectricEnergy IS NOT NULL THEN tm_start.ElectricEnergy ELSE 0 END ) as StartEnergy, SUM( CASE WHEN tm_end.ElectricEnergy IS NOT NULL THEN tm_end.ElectricEnergy ELSE 0 END ) as EndEnergy, MIN(tm_start.UpdateTime) as StartTime, MAX(tm_end.UpdateTime) as EndTime FROM HourlyBoundaries hb CROSS JOIN ( SELECT DISTINCT DeviceID, Name, Workshop FROM RSWS_TempMonitor_Copy WHERE Workshop = '1#办公楼' AND ElectricEnergy IS NOT NULL
AND DeviceID = #{deviceId}
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) devices LEFT JOIN RSWS_TempMonitor_Copy tm_start ON ( tm_start.DeviceID = devices.DeviceID AND tm_start.Name = devices.Name AND tm_start.Workshop = '1#办公楼' AND tm_start.ElectricEnergy IS NOT NULL AND tm_start.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '1#办公楼' AND inner_tm.UpdateTime <= hb.HourStart AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime DESC ) ) LEFT JOIN RSWS_TempMonitor_Copy tm_end ON ( tm_end.DeviceID = devices.DeviceID AND tm_end.Name = devices.Name AND tm_end.Workshop = '1#办公楼' AND tm_end.ElectricEnergy IS NOT NULL AND tm_end.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '1#办公楼' AND inner_tm.UpdateTime >= hb.HourEnd AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime ASC ) ) GROUP BY HourStart, HourEnd ) SELECT '1#办公楼' as deviceId, '1#办公楼' as name, '1#办公楼' as workshop, HourStart as hour, StartEnergy as startEnergy, EndEnergy as endEnergy, StartTime as startTime, EndTime as endTime, CASE WHEN StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE NULL END as energyConsumption FROM DeviceHourlyData WHERE StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL ORDER BY HourStart

WITH DailyBoundaries AS ( -- 生成最近7天的每日边界 SELECT DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 8, CAST(GETDATE() AS DATE)) as DayStart, DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 7, CAST(GETDATE() AS DATE)) as DayEnd FROM ( SELECT TOP 7 1 as DummyColumn FROM sys.objects ) dummy ), DeviceDailyData AS ( SELECT DayStart, SUM( CASE WHEN tm_start.ElectricEnergy IS NOT NULL THEN tm_start.ElectricEnergy ELSE 0 END ) as StartEnergy, SUM( CASE WHEN tm_end.ElectricEnergy IS NOT NULL THEN tm_end.ElectricEnergy ELSE 0 END ) as EndEnergy FROM DailyBoundaries db CROSS JOIN ( SELECT DISTINCT DeviceID, Name, Workshop FROM RSWS_TempMonitor_Copy WHERE Workshop = '1#办公楼' AND ElectricEnergy IS NOT NULL
AND DeviceID = #{deviceId}
) devices LEFT JOIN RSWS_TempMonitor_Copy tm_start ON ( tm_start.DeviceID = devices.DeviceID AND tm_start.Name = devices.Name AND tm_start.Workshop = '1#办公楼' AND tm_start.ElectricEnergy IS NOT NULL AND tm_start.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '1#办公楼' AND inner_tm.UpdateTime <= db.DayStart AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime DESC ) ) LEFT JOIN RSWS_TempMonitor_Copy tm_end ON ( tm_end.DeviceID = devices.DeviceID AND tm_end.Name = devices.Name AND tm_end.Workshop = '1#办公楼' AND tm_end.ElectricEnergy IS NOT NULL AND tm_end.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '1#办公楼' AND inner_tm.UpdateTime < db.DayEnd AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime DESC ) ) GROUP BY DayStart ) SELECT '1#办公楼' as deviceId, '1#办公楼' as name, '1#办公楼' as workshop, DayStart as day, StartEnergy as startEnergy, EndEnergy as endEnergy, CASE WHEN StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE NULL END as energyConsumption FROM DeviceDailyData WHERE StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL ORDER BY DayStart

WITH DailyBoundaries AS ( -- 生成时间范围内的每日边界 SELECT DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, CAST( #{startTime} DATEADD(DAY, -7, GETDATE()) AS DATE) ) as DayStart, DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)), CAST( #{startTime} DATEADD(DAY, -7, GETDATE()) AS DATE) ) as DayEnd FROM ( SELECT TOP ( DATEDIFF(DAY, #{startTime} DATEADD(DAY, -7, GETDATE()), #{endTime} GETDATE() ) + 1 ) 1 as DummyColumn FROM sys.objects ) dummy ), DeviceDailyData AS ( SELECT DayStart, SUM( CASE WHEN tm_start.ElectricEnergy IS NOT NULL THEN tm_start.ElectricEnergy ELSE 0 END ) as StartEnergy, SUM( CASE WHEN tm_end.ElectricEnergy IS NOT NULL THEN tm_end.ElectricEnergy ELSE 0 END ) as EndEnergy FROM DailyBoundaries db CROSS JOIN ( SELECT DISTINCT DeviceID, Name, Workshop FROM RSWS_TempMonitor_Copy WHERE Workshop = '1#办公楼' AND ElectricEnergy IS NOT NULL
AND DeviceID = #{deviceId}
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) devices LEFT JOIN RSWS_TempMonitor_Copy tm_start ON ( tm_start.DeviceID = devices.DeviceID AND tm_start.Name = devices.Name AND tm_start.Workshop = '1#办公楼' AND tm_start.ElectricEnergy IS NOT NULL AND tm_start.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '1#办公楼' AND inner_tm.UpdateTime <= db.DayStart AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime DESC ) ) LEFT JOIN RSWS_TempMonitor_Copy tm_end ON ( tm_end.DeviceID = devices.DeviceID AND tm_end.Name = devices.Name AND tm_end.Workshop = '1#办公楼' AND tm_end.ElectricEnergy IS NOT NULL AND tm_end.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '1#办公楼' AND inner_tm.UpdateTime < db.DayEnd AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime DESC ) ) GROUP BY DayStart ) SELECT '1#办公楼' as deviceId, '1#办公楼' as name, '1#办公楼' as workshop, DayStart as day, StartEnergy as startEnergy, EndEnergy as endEnergy, CASE WHEN StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE NULL END as energyConsumption FROM DeviceDailyData WHERE StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL ORDER BY DayStart
